using System;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Diagnostics;using System.Threading;
namespace LoopPedal {
sealed class MidiClockOutput:IDisposable {
 [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Auto)]struct Caps{public ushort manufacturer,product;public uint version;[MarshalAs(UnmanagedType.ByValTStr,SizeConst=32)]public string name;public ushort technology,voices,notes,channel;public uint support;}
 [DllImport("winmm.dll")]static extern uint midiOutGetNumDevs();[DllImport("winmm.dll",CharSet=CharSet.Auto)]static extern uint midiOutGetDevCaps(UIntPtr device,out Caps caps,uint size);[DllImport("winmm.dll")]static extern uint midiOutOpen(out IntPtr handle,uint device,IntPtr callback,IntPtr instance,uint flags);[DllImport("winmm.dll")]static extern uint midiOutShortMsg(IntPtr handle,uint value);[DllImport("winmm.dll")]static extern uint midiOutClose(IntPtr handle);[DllImport("winmm.dll")]static extern uint timeBeginPeriod(uint value);[DllImport("winmm.dll")]static extern uint timeEndPeriod(uint value);
 readonly Engine engine;readonly Thread thread;IntPtr handle;volatile bool running=true;public static long Now(){return (long)(Stopwatch.GetTimestamp()*(1000000000.0/Stopwatch.Frequency));}
 public static string[] Names(){var names=new List<string>();for(uint i=0;i<midiOutGetNumDevs();i++){Caps c;names.Add(midiOutGetDevCaps((UIntPtr)i,out c,(uint)Marshal.SizeOf(typeof(Caps)))==0?c.name:"MIDI "+(i+1));}return names.ToArray();}
 public MidiClockOutput(Engine e,int device){engine=e;uint error=midiOutOpen(out handle,(uint)device,IntPtr.Zero,IntPtr.Zero,0);if(error!=0)throw new Exception("MIDI output unavailable ("+error+")");thread=new Thread(Run){IsBackground=true,Name="Agent Looper MIDI clock",Priority=ThreadPriority.Highest};thread.Start();}
 void Send(int value){if(midiOutShortMsg(handle,(uint)value)!=0)engine.Error="MIDI output disconnected";}
 void Run(){timeBeginPeriod(1);try{long next=Now(),restart=engine.RestartSerial;bool playing=false,started=false;while(running){if(engine.MidiClock.mode!=2){if(playing)Send(252);playing=false;next=Now();Thread.Sleep(5);continue;}bool active;double tempo;long serial;lock(engine.Gate){active=engine.Playing&&engine.Layers.Count>0||engine.Recording||engine.Partner!=null&&(engine.Partner.Playing&&engine.Partner.Layers.Count>0||engine.Partner.Recording);tempo=engine.BPM;serial=engine.RestartSerial;}if(active!=playing||serial!=restart&&active){Send(active?(!started||serial!=restart?250:251):252);if(active){started=true;next=Now();}playing=active;restart=serial;}long period=(long)(60000000000.0/Math.Max(20,Math.Min(300,tempo))/24),now=Now();if(now>=next){Send(248);next+=period;if(now-next>period)next=now+period;}else Thread.Sleep(1);}if(playing)Send(252);}finally{timeEndPeriod(1);}}
 public void Dispose(){running=false;if(Thread.CurrentThread!=thread)thread.Join(500);if(handle!=IntPtr.Zero){midiOutClose(handle);handle=IntPtr.Zero;}}
}
sealed partial class Engine {
 public readonly MidiClockState MidiClock=new MidiClockState();public long RestartSerial;public bool MidiFinishPending;
 public void ApplyMidiClock(){if(MidiClock.mode!=1)return;if(MidiClock.last!=0){BPM=MidiClock.bpm;if(Partner!=null)Partner.BPM=BPM;}int command=MidiClock.command();if(command==250){Performance.restart();gridOriginAudio=AudioFrame;gridSet=true;MidiStart(this);if(Partner!=null){Partner.gridOriginAudio=Partner.AudioFrame;Partner.gridSet=true;MidiStart(Partner);}}else if(command==251){Playing=Layers.Count>0;if(Partner!=null)Partner.Playing=Partner.Layers.Count>0;}else if(command==252){Playing=false;MidiFinishPending=Recording;if(Partner!=null){Partner.Playing=false;Partner.MidiFinishPending=Partner.Recording;}}}
 static void MidiStart(Engine bank){bank.Frame=bank.LoopOrigin;bank.PlaybackPending=false;bank.Playing=bank.Layers.Count>0;bank.MidiFinishPending=bank.Recording;foreach(var l in bank.Layers)if(l.Stream!=null)l.Stream.Seek(bank.Frame);}
}
}
